import unittest

from invoice import invoice_total
from money import round_money
from receipt import receipt_total


class TestRoundMoney(unittest.TestCase):
    def test_rounds_half_away_from_zero(self):
        self.assertEqual(round_money(0.145), 0.15)
        self.assertEqual(round_money(0.335), 0.34)
        self.assertEqual(round_money(1.005), 1.01)
        self.assertEqual(round_money(2.675), 2.68)

    def test_rounds_negatives_half_away_from_zero(self):
        self.assertEqual(round_money(-0.145), -0.15)
        self.assertEqual(round_money(-2.675), -2.68)

    def test_rounds_down_below_the_halfway_point(self):
        self.assertEqual(round_money(0.144), 0.14)
        self.assertEqual(round_money(-0.144), -0.14)

    def test_leaves_exact_cent_amounts_alone(self):
        self.assertEqual(round_money(0.29), 0.29)
        self.assertEqual(round_money(10), 10.0)
        self.assertEqual(round_money(0), 0.0)

    def test_absorbs_binary_float_representation_error(self):
        # 0.7 * 3 is 2.0999999999999996 in binary floating point.
        self.assertEqual(round_money(0.7 * 3), 2.1)
        # 0.1 + 0.2 is 0.30000000000000004.
        self.assertEqual(round_money(0.1 + 0.2), 0.3)

    def test_returns_a_float(self):
        self.assertIsInstance(round_money(0.145), float)


class TestReceiptTotal(unittest.TestCase):
    def test_two_items_at_the_halfway_point(self):
        # The reported bug: this showed 0.28.
        self.assertEqual(receipt_total([0.145, 0.145]), 0.29)

    def test_empty_receipt(self):
        self.assertEqual(receipt_total([]), 0.0)

    def test_ordinary_prices_are_unchanged(self):
        self.assertEqual(receipt_total([1.99, 2.50, 0.75]), 5.24)


class TestInvoiceTotal(unittest.TestCase):
    def test_quantity_at_the_halfway_point(self):
        self.assertEqual(invoice_total([(0.145, 2)]), 0.29)

    def test_quantity_with_float_representation_error(self):
        self.assertEqual(invoice_total([(0.7, 3)]), 2.1)

    def test_multiple_lines(self):
        self.assertEqual(invoice_total([(1.99, 2), (0.505, 1)]), 4.49)


if __name__ == "__main__":
    unittest.main()

